function ago(iso){if(!iso)return "";var d=(Date.now()-new Date(iso))/3600000;return d<1?"just now":d<24?Math.round(d)+" h ago":d<48?"yesterday":Math.round(d/24)+" days ago";}
var STATUS=[["new","New"],["contacted","Contacted"],["trial","On trial"],["done","Trial done"],["joined","Joined"],["no","No"]];
function stLabel(st){st=st||"new";if(st==="won")st="joined";var m=STATUS.filter(function(x){return x[0]===st;})[0];return m?m[1]:st;}
function stClass(st){st=st||"new";if(st==="won")st="joined";return st;}
function ownerName(uid){return uid==="15a011b9-e222-45f0-8eb9-d5338da935d1"?"Jake":uid==="f0cbff5d-db5c-4b86-8d35-9b94ad8a38ce"?"Alison":uid==="f2dfab30-b271-4c3e-a44e-8b00d489c2c6"?"Jerson":"";}
function leadCard(l,kind){var st=stClass(l.status),open=AD.open===l.id,ph=String(l.phone||"").replace(/\s/g,""),nm=((l.first_name||"")+" "+(l.last_name||"")).trim()||"Lead";
  var tl=[];tl.push("Signed up "+ago(l.created_at));if(l.contacted_at)tl.push("contacted "+ago(l.contacted_at)+(ownerName(l.contacted_by)?" by "+ownerName(l.contacted_by):""));if(l.started_at)tl.push("trial started "+fmtDate(new Date(l.started_at)));if(st==="joined"&&l.updated_at)tl.push("joined "+ago(l.updated_at));
  return '<div class="card2 lead'+(open?" open":"")+'" style="margin-bottom:10px"><div><div class="n">'+E(nm)+'</div><div class="s">'+E(kind||l.challenge||l.source||"Website")+(l.suburb?" · "+E(l.suburb):"")+(l.package?" · "+E(l.package):"")+'</div><div class="tl">'+tl.join(" · ")+(l.notes&&!open?'<br>'+E(l.notes):'')+'</div></div>'+
   (open?'':'<div class="acts"><button class="st '+st+'" onclick="lg2LeadOpen(\''+l.id+'\')">'+stLabel(st)+' ›</button>'+(ph?'<a class="call" href="tel:'+E(ph)+'">Call</a>':'')+'</div>')+
   (open?'<div class="more"><div class="stlist">'+STATUS.map(function(x){return '<button class="'+(st===x[0]?"on":"")+'" onclick="lg2LeadStatus(\''+l.id+'\',\''+x[0]+'\')">'+x[1]+'</button>';}).join("")+'</div><div class="ctrow">'+(ph?'<a href="tel:'+E(ph)+'">Call</a><a href="sms:'+E(ph)+'">Text</a>':'')+(l.email?'<a href="mailto:'+E(l.email)+'">Email</a>':'')+'</div><textarea placeholder="Note, e.g. texted, coming Tuesday 6am" onblur="lg2LeadNote(\''+l.id+'\',this)">'+E(l.notes||"")+'</textarea><div style="display:flex;justify-content:flex-end;margin-top:8px"><button class="btn sm ghost" onclick="lg2LeadOpen(null)">Close</button></div></div>':'')+'</div>';}
