window.lg2LeadStatus=function(id,st){var l=(AD.data.leads.data||[]).filter(function(x){return x.id===id;})[0];var now=new Date().toISOString(),up={status:st,updated_at:now};if(st==="contacted"&&!(l&&l.contacted_at)){up.contacted_at=now;up.contacted_by=me();}if(st==="trial"&&!(l&&l.started_at))up.started_at=now;
  sb.from("challenge_leads").update(up).eq("id",id).then(function(r){if(r.error){T(r.error.message);return;}if(l)Object.assign(l,up);buzz(8);T(stLabel(st));renderAdmin();});};
window.lg2NutriStatus=function(id,st){var r=(AD.data.nutri.data||[]).filter(function(x){return x.id===id;})[0];var now=new Date().toISOString(),up={status:st,updated_at:now};if(st==="contacted"&&!(r&&r.contacted_at)){up.contacted_at=now;up.contacted_by=me();}
  sb.from("nutrition_requests").update(up).eq("id",id).then(function(q2){if(q2.error){T(q2.error.message);return;}if(r)Object.assign(r,up);buzz(8);T("Saved");renderAdmin();});};
window.lg2NutriNote=function(id,el){var r=(AD.data.nutri.data||[]).filter(function(x){return x.id===id;})[0];if(!r||el.value===(r.notes||""))return;sb.from("nutrition_requests").update({notes:el.value,updated_at:new Date().toISOString()}).eq("id",id).then(function(q2){if(q2.error){T(q2.error.message);return;}r.notes=el.value;T("Note saved");});};
window.lg2PostNotice=function(){var el=$id("nBody");if(!el)return;var body=el.value.trim();if(!body){T("Write the notice first");return;}sb.from("gym_announcements").update({active:false}).eq("active",true).then(function(){return sb.from("gym_announcements").insert({body:body,active:true,created_by:me()});}).then(function(r){if(r.error){T(r.error.message);return;}try{ANN=undefined;}catch(e){}T("Posted. It\'s on every home screen.");AD.loading=false;adminLoad();});};
