/* ---------- Jake & Ali: Mates tab ---------- */
var A={rows:null,at:0,look:null};
window.lgMatesTab=function(){if(!A.rows||Date.now()-A.at>60000){A.rows=A.rows||[];A.at=Date.now();cfg().then(function(){return sb.from("guest_passes").select("id,code,token,host_name,kind,membership_id,membership_term,membership_wk,price_cents,valid_date,guest_first,guest_last,guest_mobile,guest_email,repeat_flag,waiver_signed_at,waiver_verified,photo,paid_at,order_name,paid_cents,trial_started_at,joined_claimed_at,joined_verified_at,status,staff_note,created_at").gte("created_at",new Date(Date.now()-30*86400000).toISOString()).order("created_at",{ascending:false}).limit(150);}).then(function(r){A.rows=(r&&r.data)||[];if(view==="admin")render();});}
  var rows=A.rows||[],wk7=rows.filter(function(x){return Date.now()-new Date(x.created_at)<7*86400000;}),paid=wk7.filter(function(x){return x.paid_at;}),cents=paid.reduce(function(a,x){return a+(x.paid_cents||x.price_cents||0);},0),tri=wk7.filter(function(x){return x.trial_started_at;}).length,joined=wk7.filter(function(x){return x.joined_claimed_at;}).length;
  var h='<div class="stats"><div><b>'+wk7.length+'</b><i>Mates · 7 days</i></div><div><b>'+money(cents)+'</b><i>Casual paid</i></div><div><b>'+joined+'</b><i>Joined</i></div></div><div class="stats" style="grid-template-columns:1fr 1fr"><div><b>'+tri+'</b><i>Trials started</i></div><div><b>'+rows.filter(function(x){return x.repeat_flag;}).length+'</b><i>Flagged repeats</i></div></div>';
  h+='<div class="card2" style="margin-bottom:10px"><div class="k" style="font-size:10px;font-weight:800;letter-spacing:2.5px;text-transform:uppercase;color:var(--lgold)">Desk lookup</div><div style="display:flex;gap:8px;margin-top:8px"><input id="lgMateLook" placeholder="GP-XXXX" style="flex:1;background:var(--lcard);border:1px solid var(--lline2);border-radius:12px;padding:12px;color:#f3f1ec;font:700 14px Montserrat,sans-serif;text-transform:uppercase"><button class="st joined" onclick="lgMateLookup()">Find</button></div>'+(A.look?'<div style="margin-top:10px">'+mateRow(A.look,true)+'</div>':'')+'</div>';
  h+='<div class="card2"><b style="font:700 16px/1 Oswald,sans-serif;letter-spacing:1.5px;text-transform:uppercase;color:var(--lgold)">Every mate · last 30 days</b><div style="font-size:11px;color:var(--lmuted);margin:4px 0 6px;line-height:1.5">Who, whose mate, what they bought, and whether the waiver, photo and payment are on file. Tap a photo to see it big.</div>'+(rows.length?rows.map(function(x){return mateRow(x,false);}).join(""):'<div class="muted" style="padding:10px 0;font-size:12.5px">No passes yet.</div>')+'</div>';
  return h;};
function mateRow(x,big){var l=prodLabel({kind:x.kind,membership_id:x.membership_id,membership_wk:x.membership_wk,membership_term:x.membership_term,price_cents:x.price_cents});var name=((x.guest_first||"")+" "+(x.guest_last||"")).trim()||"No details yet";var ini=((x.guest_first||"")[0]||"")+((x.guest_last||"")[0]||"");
  var tags=[];tags.push('<span class="'+(x.waiver_signed_at?(x.waiver_verified?"ok":"wait"):"bad")+'">'+(x.waiver_signed_at?(x.waiver_verified?"Waiver confirmed":"Waiver self-reported"):"No waiver")+'</span>');tags.push('<span class="'+(x.photo?"ok":"bad")+'">'+(x.photo?"Photo":"No photo")+'</span>');
  if(x.kind==="trial")tags.push('<span class="'+(x.trial_started_at?"ok":"wait")+'">'+(x.trial_started_at?"Trial registered":"Trial not started")+'</span>');else if(x.kind==="membership")tags.push('<span class="'+(x.joined_verified_at?"ok":x.joined_claimed_at?"wait":"")+'">'+(x.joined_verified_at?"Joined · verified":x.joined_claimed_at?"Says DD set up · verify":"Not signed up")+'</span>');else tags.push('<span class="'+(x.paid_at?"ok":"wait")+'">'+(x.paid_at?"Paid "+money(x.paid_cents||x.price_cents)+(x.order_name?" · "+E(x.order_name):""):"Unpaid")+'</span>');
  if(x.repeat_flag)tags.push('<span class="bad">'+E(x.repeat_flag)+'</span>');if(x.status==="cancelled")tags.push('<span class="bad">Cancelled</span>');
  var acts='';if(isOwner()){if(x.waiver_signed_at&&!x.waiver_verified)acts+='<button onclick="lgMateAct(\''+x.id+'\',\'waiver\')">Waiver sighted ✓</button>';if(x.kind==="membership"&&x.joined_claimed_at&&!x.joined_verified_at)acts+='<button onclick="lgMateAct(\''+x.id+'\',\'joined\')">Joined ✓</button>';if(x.status!=="cancelled"&&x.status!=="done")acts+='<button onclick="lgMateAct(\''+x.id+'\',\'cancel\')">Cancel pass</button>';}
  if(x.guest_mobile)acts+='<a class="st" style="text-decoration:none" href="tel:'+E(x.guest_mobile.replace(/\s/g,""))+'">Call</a>';
  return '<div class="mrow">'+(x.photo?'<img class="face" src="'+x.photo+'" alt="" onclick="lgMatePhoto(this.src)" style="cursor:zoom-in">':'<span class="face ph">'+E(ini||"?")+'</span>')+'<div><b class="n">'+E(name)+' <span style="color:var(--lmuted);font-weight:600">· '+E(x.code)+'</span></b><small>'+E(l.n)+' · '+E(l.price)+' · mate of '+E(x.host_name||"?")+' · '+E(new Date(x.created_at).toLocaleString("en-AU",{weekday:"short",day:"numeric",month:"short",hour:"numeric",minute:"2-digit"}))+(x.guest_mobile?' · '+E(x.guest_mobile):'')+(x.guest_email?' · '+E(x.guest_email):'')+'</small><div class="tags">'+tags.join("")+'</div>'+(acts?'<div class="acts">'+acts+'</div>':'')+'</div></div>';}
window.lgMateLookup=function(){var c=($id("lgMateLook")||{}).value||"";c=c.trim().toUpperCase();if(!c)return;sb.from("guest_passes").select("*").eq("code",c).maybeSingle().then(function(r){if(!r.data){T("No pass with that code");return;}A.look=r.data;render();});};
window.lgMateAct=function(id,what){var up=what==="waiver"?{waiver_verified:true,verified_by:me(),verified_at:new Date().toISOString()}:what==="joined"?{joined_verified_at:new Date().toISOString(),verified_by:me(),verified_at:new Date().toISOString()}:{status:"cancelled"};if(what==="cancel"&&!confirm("Cancel this pass? The mate's link stops working."))return;
  sb.from("guest_passes").update(up).eq("id",id).then(function(r){if(r.error){T(r.error.message);return;}T("Saved");A.rows=null;A.look=null;lgMatesTab();});};
